style.css:
@-moz-document domain("youtube.com") {
html, body {
        background-image: url(https://i.postimg.cc/C57Pq45Q/5596694045289f3fe965814ad58d6461.jpg) !important;
        background-size: cover !important;
        background-attachment: fixed !important;
        background-position: center !important;
    }

    ytd-app, #content, #page-manager, ytd-browse, ytd-two-column-browse-results-renderer, #primary, #secondary {
        background: transparent !important;
    }

    ytd-masthead, #masthead-container, #guide-content, #guide-inner-content {
        background: rgba(24, 18, 20, 0.85) !important;
    }

    html, html[dark], body, ytd-app {
        --yt-spec-base-background: rgba(24, 18, 20, 0.85) !important;
        --yt-spec-text-primary: rgb(225, 140, 155) !important;
        --yt-spec-text-secondary: rgba(225, 140, 155, 0.8) !important;
    }

    #container.ytd-searchbox, .ytSearchboxComponentInputBox, .ytSearchboxComponentInputBoxDark {
        background-color: rgba(28, 20, 22, 0.85) !important;
        border: 1px solid rgb(225, 140, 155) !important;
        color: rgb(225, 140, 155) !important;
    }

    #search-icon-legacy.ytd-searchbox, .ytSearchboxComponentSearchButton, .ytSearchboxComponentSearchButtonDark {
        background-color: rgba(225, 140, 155, 0.25) !important;
        border: 1px solid rgb(225, 140, 155) !important;
    }

    input#search, .ytSearchboxComponentInput, .ytSearchboxComponentInput::placeholder {
        color: rgb(225, 140, 155) !important;
    }

    yt-chip-cloud-chip-renderer #chip-container.yt-chip-cloud-chip-renderer {
        background-color: rgba(225, 140, 155, 0.18) !important;
        color: rgb(225, 140, 155) !important;
        border: 1px solid rgba(225, 140, 155, 0.35) !important;
    }

    yt-chip-cloud-chip-renderer[selected] #chip-container.yt-chip-cloud-chip-renderer {
        background-color: rgb(225, 140, 155) !important;
        color: #181214 !important;
    }

    /* Тёмная полупрозрачная подложка под названия видео */
    ytd-rich-item-renderer #details,
    #details.ytd-rich-grid-media,
    .yt-lockup-metadata-view-model-wiz {
        background-color: rgba(24, 15, 18, 0.82) !important;
        border-radius: 10px !important;
        padding: 8px 10px !important;
        margin-top: 6px !important;
    }

    /* Розовый текст для всей страницы (меню, заголовки, каналы) */
    yt-formatted-string,
    .yt-core-attributed-string,
    #video-title,
    #channel-name a,
    #metadata-line span {
        color: rgb(225, 140, 155) !important;
    }

    /* Тёмная подложка под описание каждого видео */
    yt-lockup-metadata-view-model,
    .yt-lockup-metadata-view-model-wiz,
    ytd-rich-item-renderer #details,
    #meta.ytd-rich-grid-media {
        background-color: rgba(24, 15, 18, 0.82) !important;
        border-radius: 10px !important;
        padding: 8px 10px !important;
        margin-top: 6px !important;
    }

    /* Розовый цвет и тёмная тень для текста, чтобы читался на любом фоне */
    yt-lockup-metadata-view-model span,
    yt-lockup-metadata-view-model a,
    #video-title,
    #metadata-line span {
        color: rgb(225, 140, 155) !important;
        text-shadow: 0 1px 3px rgba(0, 0, 0, 0.9) !important;
    }
}
